CREATE DEFINER=`toolsmart_roa_app`@`89.77.122.32` FUNCTION `cena_pozycji`(p_idp int) RETURNS decimal(12,2)
    DETERMINISTIC
BEGIN
DECLARE p_wartosc decimal(12,2);
DECLARE p_liczbadni int;

set p_liczbadni=(select liczba_dni from umowa_pozycja2 where id=p_idp LIMIT 1);

IF p_liczbadni > (select IFNULL(max(liczba_dni),0) from umowa_pozycja2_warunek where oplata2>0 and id_pozycji=p_idp) THEN 
    set p_wartosc=(select case when w.oplata2 =0 then w.oplata1 else w.oplata2 end from umowa_pozycja2 p inner join umowa_pozycja2_warunek w on p.id=w.id_pozycji where p.id=p_idp and p.liczba_dni>=w.liczba_dni order by w.id desc LIMIT 1);
ELSE 
    set p_wartosc=(select case when w.oplata2 =0 then w.oplata1 else w.oplata2 end from umowa_pozycja2 p inner join umowa_pozycja2_warunek w on p.id=w.id_pozycji where p.id=p_idp and p.liczba_dni<=w.liczba_dni order by w.id LIMIT 1);
END IF;

return p_wartosc;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
