CREATE DEFINER=`toolsmart_roa_app`@`89.77.122.32` FUNCTION `generuj_opis_oplaty`(p_opis  varchar(400),p_op1 decimal(14,4),p_op2 decimal(14,4)) RETURNS varchar(400) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
    DETERMINISTIC
BEGIN
return replace(REPLACE(p_opis,'$1',CAST(cast(
case when p_op1 is null then 0 else p_op1 end as decimal(12,2)) AS CHAR)),'$2',CAST(cast(
case when p_op2 is null then 0 else p_op2 end as decimal(12,2)) AS CHAR));
end ;;
