CREATE DEFINER=`toolsmart_roa_app`@`89.77.122.32` FUNCTION `rozlicz_pozycje`(p_idp int) RETURNS decimal(12,2)
    DETERMINISTIC
BEGIN
DECLARE p_wartosc  decimal(12,2);

set p_wartosc=(

select 
case when w.OPLATA2 =0  then w.oplata1 else w.OPLATA2 end*p.LICZBA_DNI
from umowa_pozycja2 p inner join umowa_pozycja2_warunek w on p.id=w.ID_POZYCJI
where p.id=p_idp and p.LICZBA_DNI>=w.LICZBA_DNI order by w.id desc
);



return p_wartosc;

end ;;
