CREATE DEFINER=`toolsmart_roa_app`@`89.77.122.32` PROCEDURE `getartykuly`(p_dod datetime, p_ddo datetime)
BEGIN
select *
from artykuly a
left join (
select p.ID_ARTYKULU ida,count(u.id) ile from umowa_pozycja2 p inner join umowa2 u on p.ID_umowy=u.id
where (u.data_od between p_dod and p_ddo) or (u.data_do between p_dod and p_ddo) 
group by p.ID_ARTYKULU) d on d.ida=a.id;
END ;;
