CREATE DEFINER=`toolsmart_roa_app`@`89.77.122.32` PROCEDURE `getartykuly2`(p_idumowy numeric)
BEGIN
DECLARE p_dod datetime;
DECLARE p_ddo datetime;
DECLARE p_typ char(1);

SELECT data_od, data_do, typ INTO p_dod, p_ddo, p_typ FROM umowa2 where id=p_idumowy;

select *
from artykuly a
left join (
select p.ID_ARTYKULU ida,count(u.id) ile 
from umowa_pozycja2 p inner join umowa2 u on p.ID_umowy=u.id
where (u.data_od>=p_dod and u.data_od<=p_ddo) or (u.data_do>= p_dod and u.data_do<= p_ddo) 
group by p.ID_ARTYKULU) d on d.ida=a.id
where a.rodzaj=(case when p_typ='u' then 'usługa' else 'artykuł' end)
order by a.`data dodania` desc;
END ;;
DELIMITER ;
