CREATE DEFINER=`toolsmart_roa_app`@`89.77.122.32` PROCEDURE `getartykuly5`(p_idoddzialu int)
BEGIN
select a.*,d.ile
from artykulyy a
left join (
select ID_ARTYKULU ida,count(*) ile
from umowa_pozycja3 where NOW() between data_dostawy and DATE_ADD(data_dostawy, INTERVAL liczba_dni DAY)
group by id_artykulu
) d on d.ida=a.id
where a.id_oddzialu=p_idoddzialu
order by a.`data dodania` desc;
END ;;
DELIMITER ;
