CREATE DEFINER=`toolsmart_roa_app`@`89.77.122.32` PROCEDURE `getumowyartykulu7`(p_datadostawy datetime ,p_iledni int, p_rodzaj int)
BEGIN
DECLARE p_dataodbioru date;

set p_dataodbioru=DATE_ADD(p_datadostawy, INTERVAL p_iledni-1 DAY);


select a.id,nazwa,a.nr_rejestracyjny,a.nr_seryjny,a.rodzaj,a.wlasciciel,a.kategoria,a.`wartość odtworzeniowa`,a.marka,a.model,a.uwagi,a.`data dodania`,poz.ile
from artykulyy a
left join (


select p.ID_ARTYKULU ida,count(*) ile
from umowa_pozycja3 p inner join umowa2 u on p.id_umowy=u.id 
where 
data_dostawy < p_datadostawy and DATE_ADD(p.data_dostawy, INTERVAL p.liczba_dni DAY) between p_datadostawy and p_dataodbioru
or  
data_dostawy < p_datadostawy and DATE_ADD(p.data_dostawy, INTERVAL p.liczba_dni DAY)>p_dataodbioru
or
data_dostawy between p_datadostawy and p_dataodbioru and DATE_ADD(p.data_dostawy, INTERVAL p.liczba_dni DAY)>p_dataodbioru
or
data_dostawy between p_datadostawy and p_dataodbioru  and DATE_ADD(p.data_dostawy, INTERVAL p.liczba_dni DAY) between p_datadostawy and p_dataodbioru

group by p.id_artykulu
) poz on poz.ida=a.id
where a.rodzaj=case when p_rodzaj=1 then 'artykuł' else 'usługa' end;
END ;;
