CREATE DEFINER=`toolsmart_roa_app`@`89.77.122.32` PROCEDURE `sprumowyartykulu`(p_idumowy numeric,p_idartykulu numeric)
BEGIN
DECLARE p_dod datetime;
DECLARE p_ddo datetime;
DECLARE p_typ char(1);

SELECT data_od, data_do, typ INTO p_dod, p_ddo, p_typ FROM umowa2 where id=p_idumowy;

select u.numer,CAST(u.data_od AS DATE) data_od,CAST(u.data_do AS DATE) data_do
from umowa2 u
where u.id in (select distinct u.id from umowa_pozycja2 p inner join umowa2 u on p.id_umowy=u.id
where (u.data_od>=p_dod and u.data_od<=p_ddo) or (u.data_do>= p_dod and u.data_do<= p_ddo) and p.ID_ARTYKULU=p_idartykulu);
END ;;
